parameters.jsCode:
// 整理 AI 回傳結果並確保為 JSON 物件
const rawOutput = $input.first().json.output || '';
let parsedAi = {};
try {
  const cleanJson = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  parsedAi = JSON.parse(cleanJson);
} catch (e) {
  parsedAi = {
    raw_output: rawOutput,
    sentiment: '未知',
    summary: 'AI 回傳非標準 JSON 格式'
  };
}

const inputData = $('提取評論內容').item.json;

return [{
  json: {
    status: 'success',
    customer_name: inputData.customerName,
    original_feedback: inputData.feedbackText,
    analysis: parsedAi,
    analyzed_at: new Date().toISOString()
  }
}];
